// In-browser fake of the facade backed by fixture JSON (api/fixtures/*.json), used by Vitest, Playwright and
// `vite --mode mock`. Implementation: WP-14. FROZEN signatures.
//
// Each createMockApi() call owns its own in-memory state, seeded from the fixtures (generated by scripts/mockfixture).
// Nothing here touches the network. Timers appear only when a latency is configured; otherwise calls settle on
// microtasks alone. Every call is recorded when it is made, and a failing call changes nothing.
import type { Api } from "./index";
import { AppError, type ErrorCode } from "./errors";
import { createMemoryBus, type EventBus, type EventMap, type EventName } from "./events";
import { FIXTURE_APP, FIXTURE_CATALOG, FIXTURE_CONFIGS, FIXTURE_TICKETS, FIXTURE_TICKETS_HANDBUILT, FIXTURE_VIEWS } from "./mock-fixtures";
import { idleSync, LANE_LABEL, laneInfos, refreshView, viewOptions } from "./mock-views";
import type * as T from "./types";

export interface MockOptions {
  /** Latency per call in ms (default 0). */
  latency?: number;
  /** Methods that should reject, e.g. { "config.update": { code: "db", times: 1 } }. */
  failures?: Record<string, { code: string; message?: string; field?: string; times?: number }>;
  /** Extra settle delay per method in ms (Playwright: lets a "sending…" state stay on screen). */
  holdMs?: Record<string, number>;
  /** Serve the hand-built mockup MOB-1421 instead of the Go golden (the T7 component tests assert its content). */
  handBuiltTickets?: boolean;
  /** Auto-update state (ADR 0016). The default is a build with no channel: no Update button, no checks. */
  update?: Partial<T.UpdateStatus>;
  /** How update.install ends: "ok" (default: restarting), or a failure code shown in the dialog. */
  updateInstall?: "ok" | "verify" | "download";
}

export interface MockApi extends Api {
  /** Every call made, in order, as "service.method" (perf tests assert zero calls on person switch). */
  readonly calls: { method: string; args: unknown[] }[];
  resetCalls(): void;
  /** The in-memory event bus the mock emits on (install it with setEventBus). */
  readonly bus: EventBus & { emit<E extends EventName>(name: E, payload: EventMap[E]): void };
}

const WALK: T.WalkLane[] = ["todo", "prog", "review", "qa"];
const AXIS = FIXTURE_VIEWS[0]?.axis ?? [];

const clone = <X>(x: X): X => (x === undefined ? x : (JSON.parse(JSON.stringify(x)) as X));
const notFound = (what: string): AppError => new AppError("not_found", `${what} not found.`);
const invalid = (message: string, field = ""): AppError => new AppError("validation", message, "", false, field);
const notYet = (): never => {
  throw new AppError("not_implemented", "History arrives in a later milestone.");
};
const matches = (query: string, ...fields: string[]): boolean => {
  const q = query.trim().toLowerCase();
  return q === "" || fields.some((f) => f.toLowerCase().includes(q));
};
/** Deterministic Fisher-Yates with a fixed seed, so "shuffle" is repeatable in tests. */
function seededOrder<X>(xs: X[], seed: number): X[] {
  const out = [...xs];
  let s = seed >>> 0 || 1;
  for (let i = out.length - 1; i > 0; i--) {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    const j = s % (i + 1);
    const a = out[i];
    const b = out[j];
    if (a !== undefined && b !== undefined) {
      out[i] = b;
      out[j] = a;
    }
  }
  return out;
}

// ── ticket modal (F12) ──
/** The connected user in mock mode (freeze decision 6: never a real person). */
const SELF: T.PersonRef = { accountId: "mock-user", name: "Mock User", initials: "MU", self: true };
const TICKET_DAYS = 21;
/** The transitions shown in design/mockups/ticket-edit-states-1920x1080.png (Done and Won't Do need a Jira screen). */
const TRANSITIONS: { id: string; name: string; toStatusName: string; toLane: T.Lane; needsScreen: boolean }[] = [
  { id: "11", name: "To Do", toStatusName: "To Do", toLane: "todo", needsScreen: false },
  { id: "31", name: "In Review", toStatusName: "In Review", toLane: "review", needsScreen: false },
  { id: "41", name: "QA", toStatusName: "QA", toLane: "qa", needsScreen: false },
  { id: "51", name: "Done", toStatusName: "Done", toLane: "done", needsScreen: true },
  { id: "61", name: "Won't Do", toStatusName: "Won't Do", toLane: "done", needsScreen: true },
];
/** Custom fields pinned in mock mode, in the order the mockups show; the other custom fields follow A–Z. */
const PINNED_FIELDS = [
  "customfield_10101", "customfield_10102", "customfield_10103", "customfield_10104", "customfield_10105",
  "customfield_10106", "customfield_10107", "customfield_10201", "customfield_10202", "customfield_10203",
  "customfield_10204",
];
const plainDoc = (text: string): T.AdfDoc => ({
  c: text
    .split(/\n{2,}/)
    .filter((para) => para.trim() !== "")
    .map((para) => ({ t: "p", c: [{ t: "text", x: para }] })),
});

/** A board row re-indexed onto the modal's 21-day track. */
function ticketRow(row: T.TicketView, days: number): T.TicketView {
  const shift = days - TICKET_DAYS;
  const out = clone(row);
  out.pulse.segs = out.pulse.segs
    .filter((s) => s.to - shift > 0)
    .map((s) => ({ ...s, from: Math.max(0, s.from - shift), to: s.to - shift }));
  out.pulse.marks = out.pulse.marks.filter((m) => m.day - shift >= 0).map((m) => ({ ...m, day: m.day - shift }));
  out.pulse.blocked = out.pulse.blocked
    .filter((b) => b.to - shift > 0)
    .map((b) => ({ from: Math.max(0, b.from - shift), to: b.to - shift }));
  return out;
}

/** Browser-test hooks of the mock build (Playwright): `__CUISLE_MOCK_OPTIONS__` is read at creation, `__CUISLE_MOCK_CALLS__` is the call log. */
interface MockWindow {
  __CUISLE_MOCK_OPTIONS__?: MockOptions;
  __CUISLE_MOCK_CALLS__?: { method: string; args: unknown[] }[];
}

export function createMockApi(given?: MockOptions): MockApi {
  const hooks: MockWindow | undefined = typeof window === "undefined" ? undefined : (window as unknown as MockWindow);
  const opts = given ?? hooks?.__CUISLE_MOCK_OPTIONS__;
  const latency = opts?.latency ?? 0;
  const failures = opts?.failures ?? {};
  const remaining = new Map<string, number>();
  const calls: { method: string; args: unknown[] }[] = [];
  if (hooks && !given) hooks.__CUISLE_MOCK_CALLS__ = calls;
  const bus = createMemoryBus();

  // ── state (per instance) ──
  const app = clone(FIXTURE_APP);
  let connection: T.Connection = clone(app.connection);
  const ui: T.UIState = clone(app.ui);
  const settings: Record<string, string> = { ...app.settings };
  let settingsRev = 0;
  const catalog = clone(FIXTURE_CATALOG);
  let configs: T.StandupConfig[] = clone(FIXTURE_CONFIGS);
  const views = new Map<number, T.StandupView>(clone(FIXTURE_VIEWS).map((v): [number, T.StandupView] => [v.standupId, v]));
  const archived = new Set<number>();
  let nextStandupId = configs.reduce((m, c) => Math.max(m, c.id), 0) + 1;
  let sinks: T.SinkConfig[] = [];
  let outbox: T.OutboxItem[] = [];
  let nextSinkId = 1;
  let nextOutboxId = 1;
  let nextRunId = 1;
  const tickets = new Map<number, T.TicketDetail>(clone(opts?.handBuiltTickets ? FIXTURE_TICKETS_HANDBUILT : FIXTURE_TICKETS).map((t): [number, T.TicketDetail] => [t.issueId, t]));
  const drafts = new Map<number, T.CommentInput>();
  let nextCommentId = 1;
  const customRows = [...tickets.values()].flatMap((t) => t.rail.filter((g) => g.id === "custom").flatMap((g) => g.rows));
  const fieldPrefs: T.TicketFieldPrefs = {
    pinned: PINNED_FIELDS.flatMap((id) => customRows.filter((r) => r.fieldId === id))
      .map((r, i) => ({ fieldId: r.fieldId, name: r.label, kind: r.kind, position: i, hidden: false })),
    hidden: [],
    available: customRows
      .filter((r) => !PINNED_FIELDS.includes(r.fieldId))
      .map((r) => ({ fieldId: r.fieldId, name: r.label, kind: r.kind, custom: true }))
      .sort((a, b) => a.name.localeCompare(b.name)),
  };
  // ── auto-update (ADR 0016) ──
  let update: T.UpdateStatus = {
    channel: "", currentVersion: "v1.2.0", enabled: true, lastCheckedAt: 0, lastError: "", available: null,
    phase: "idle", progress: 0, error: "", errorCode: "", ...(opts?.update ?? {}),
  };
  const updateNow = (): T.UpdateStatus => ({ ...update, enabled: settings["update.check_daily"] !== "off" });
  const setUpdate = (p: Partial<T.UpdateStatus>): void => {
    update = { ...update, ...p };
    bus.emit("update:status", clone(updateNow()));
  };
  /** Synced issues the fixtures reference without a board row (parents, inline cards), as minimal rows. */
  const refRows = new Map<number, T.TicketView>();
  const addRef = (issueId: number | undefined, key: string | undefined, summary: string, type: string, statusName: string, lane: string): void => {
    if (!issueId || !key || refRows.has(issueId) || [...views.values()].some((v) => v.tickets.some((x) => x.id === issueId))) return;
    refRows.set(issueId, {
      id: issueId, sourceId: "", key, summary, url: `${connection.baseUrl}/browse/${key}`, type, assignee: "", lane, statusName,
      daysInLane: 0, overLimit: false, blocked: false, doneAt: 0, pulse: { segs: [], marks: [], blocked: [], label: "" },
    });
  };
  const collectCards = (nodes: T.AdfNode[]): void =>
    nodes.forEach((n) => {
      if (n.t === "card") addRef(n.a?.issueId, n.a?.key, n.a?.summary ?? "", n.a?.typeKind ?? "other", n.a?.statusName ?? "", n.a?.statusLozenge ?? "todo");
      collectCards(n.c ?? []);
    });
  for (const t of tickets.values()) {
    collectCards(t.description?.c ?? []);
    if (t.parent) addRef(t.parent.issueId, t.parent.key, t.parent.summary, t.parent.typeKind, "", "todo");
  }
  let mediaCleared = false;

  // ── plumbing ──
  function takeFailure(method: string): { code: string; message?: string; field?: string } | undefined {
    const f = failures[method];
    if (!f) return undefined;
    const left = remaining.get(method) ?? f.times ?? Number.POSITIVE_INFINITY;
    if (left <= 0) return undefined;
    remaining.set(method, left - 1);
    return f;
  }

  /** Records the call, then settles after the latency with the body's result (a clone) or the injected failure. */
  function run<R>(method: string, args: unknown[], body: () => R): Promise<R> {
    calls.push({ method, args });
    const failure = takeFailure(method);
    const wait = latency + (opts?.holdMs?.[method] ?? 0);
    const pause: Promise<void> = wait > 0 ? new Promise((resolve) => setTimeout(resolve, wait)) : Promise.resolve();
    return pause.then(() => {
      if (failure) {
        throw new AppError(failure.code as ErrorCode, failure.message ?? "Mock failure.", "", false, failure.field ?? "");
      }
      return clone(body());
    });
  }

  const findCfg = (id: number): T.StandupConfig => {
    const c = configs.find((x) => x.id === id);
    if (!c) throw notFound("Standup");
    return c;
  };
  const findView = (id: number): T.StandupView => {
    const v = views.get(id);
    if (!v) throw notFound("Standup");
    return v;
  };
  const reposition = (): void => configs.forEach((c, i) => (c.position = i));
  /** A config mutation: bump rev and refresh the view's config-driven fields. */
  function changed(cfg: T.StandupConfig): void {
    cfg.rev += 1;
    const v = views.get(cfg.id);
    if (v) refreshView(v, cfg);
  }
  const ack = (cfg: T.StandupConfig): T.SaveAck => ({ rev: cfg.rev, savedAt: app.now, needsSync: cfg.needsSync });
  /** Lane column lists, and each column's dense order within its lane (set orders first, then board order). */
  const syncLaneColumns = (cfg: T.StandupConfig): void => {
    for (const l of new Set(cfg.columns.map((c) => c.lane))) {
      cfg.columns
        .filter((c) => c.lane === l)
        .sort((a, b) => (a.order ?? 1e9) - (b.order ?? 1e9))
        .forEach((c, i) => (c.order = i));
    }
    cfg.lanes = cfg.lanes.map((l) => ({ ...l, columns: cfg.columns.filter((c) => c.lane === l.lane).map((c) => c.columnName) }));
  };
  configs.forEach(syncLaneColumns); // fixtures carry no within-lane order

  function emptyView(cfg: T.StandupConfig): T.StandupView {
    return {
      standupId: cfg.id,
      rev: cfg.rev,
      generatedAt: app.now,
      today: FIXTURE_VIEWS[0]?.today ?? "",
      asOf: app.now,
      live: true,
      name: cfg.name,
      spaceKey: cfg.space?.key ?? "",
      boardName: cfg.board?.name ?? "",
      boardType: cfg.board?.type ?? "scrum",
      scope: cfg.scope,
      sprint: null,
      pulseDays: cfg.pulseDays,
      axis: clone(AXIS),
      lanes: laneInfos(cfg),
      speakers: [],
      tickets: [],
      backlog: [],
      backlogTotal: 0,
      counts: { active: 0, unassigned: 0, done: 0, backlog: 0 },
      options: viewOptions(cfg),
      sync: idleSync(cfg.id, app.now),
      warnings: [],
      previewKey: "",
      lastSyncedAt: 0,
    };
  }

  function tabs(): T.StandupTab[] {
    return configs
      .filter((c) => !archived.has(c.id))
      .map((c) => ({
        id: c.id,
        rev: c.rev,
        name: c.name,
        spaceKey: c.space?.key ?? "",
        position: c.position,
        activeCount: views.get(c.id)?.counts.active ?? 0,
        speakerCount: c.speakers.filter((s) => s.included).length,
        configured: !c.draft,
        needsSync: c.needsSync,
        lastSyncedAt: views.get(c.id)?.lastSyncedAt ?? 0,
      }));
  }

  function statuses(): T.SyncStatus[] {
    return tabs()
      .map((t) => views.get(t.id)?.sync)
      .filter((s): s is T.SyncStatus => s !== undefined);
  }

  function currentView(): T.StandupView | null {
    const live = (id: number) => !archived.has(id) && views.has(id);
    const wanted = ui.lastStandupId;
    if (live(wanted)) return views.get(wanted) ?? null;
    const first = tabs().find((t) => live(t.id));
    return first ? (views.get(first.id) ?? null) : null;
  }

  /** Every attachment across the known ticket details. */
  const allAttachments = (): T.AttachmentView[] => [...tickets.values()].flatMap((t) => t.attachments);
  const userRef = (accountId: string): T.PersonRef => {
    const u = catalog.users.find((x) => x.accountId === accountId);
    return u ? { accountId, name: u.displayName, initials: u.initials, self: false } : { accountId, name: accountId, initials: "", self: false };
  };
  const railRow = (fieldId: string, label: string, kind: string, edit: string, text: string, users: T.PersonRef[] = []): T.RailRow => ({
    fieldId,
    label,
    kind,
    edit,
    text,
    number: null,
    items: [],
    users,
    rich: null,
    raw: "",
    mono: false,
    sub: "",
    progress: null,
    url: "",
    urlLabel: "",
  });
  /** The minimal generated detail for a ticket without a hand-built fixture (freeze decision 7). */
  function generatedTicket(standupId: number, issueId: number): T.TicketDetail {
    const v = findView(standupId);
    const row = v.tickets.find((t) => t.id === issueId) ?? refRows.get(issueId);
    if (!row) throw notFound("Ticket");
    const assignee: T.PersonRef[] = row.assignee ? [userRef(row.assignee)] : [];
    return {
      issueId,
      standupId,
      asOf: app.now,
      syncedAt: v.lastSyncedAt,
      updatedAt: app.now,
      row: ticketRow(row, v.pulseDays),
      url: row.url,
      parent: null,
      pulseDays: TICKET_DAYS,
      axis: clone(v.axis.slice(-TICKET_DAYS)),
      limitDays: v.lanes.find((l) => l.lane === row.lane)?.limitDays ?? 0,
      blockedDays: 0,
      description: null,
      attachments: [],
      subtasks: [],
      subtasksDone: 0,
      linkGroups: [],
      comments: [],
      newSince: 0,
      draft: { text: "", mentions: [] },
      rail: [
        {
          id: "state",
          label: "State",
          rows: [
            railRow("status", "Status", "status", "status", row.statusName),
            railRow("assignee", "Assignee", "user", "assignee", "", assignee),
            railRow("flagged", "Flag", "flag", "flag", row.blocked ? "Flagged" : "Not flagged"),
          ],
          notSet: [],
        },
      ],
      dev: null,
      can: { transition: true, assign: true, flag: true, comment: true, reason: "" },
      warnings: [],
    };
  }
  function findTicket(standupId: number, issueId: number): T.TicketDetail {
    let t = tickets.get(issueId);
    if (!t) {
      t = generatedTicket(standupId, issueId);
      tickets.set(issueId, t);
    }
    t.standupId = standupId;
    return t;
  }
  const stateRow = (t: T.TicketDetail, fieldId: string): T.RailRow | undefined =>
    t.rail.find((g) => g.id === "state")?.rows.find((r) => r.fieldId === fieldId);
  /** Applies a change to the ticket's row and to the same row in every standup view behind the modal. */
  function patchRows(issueId: number, patch: (row: T.TicketView) => void): void {
    const t = tickets.get(issueId);
    if (t) patch(t.row);
    for (const v of views.values()) v.tickets.filter((x) => x.id === issueId).forEach(patch);
  }
  function emitUpdated(t: T.TicketDetail, changed: string[]): void {
    const standupIds = [...views.values()].filter((v) => v.tickets.some((x) => x.id === t.issueId)).map((v) => v.standupId);
    bus.emit("ticket:updated", { issueId: t.issueId, key: t.row.key, standupIds, cause: "write", changed });
    bus.emit("data:changed", { standupId: t.standupId, what: "view" });
  }
  const capMb = (): number => Number(settings["media.cache_max_mb"] ?? "1024");

  const api: Api = {
    app: {
      bootstrap: () =>
        run<T.Bootstrap>("app.bootstrap", [], () => ({
          build: app.build,
          settings: { ...settings },
          connection,
          standups: tabs(),
          ui,
          view: currentView(),
          sync: statuses(),
          recovered: false,
        })),
      setAppSetting: (key, value) =>
        run<T.SaveAck>("app.setAppSetting", [key, value], () => {
          settings[key] = value;
          settingsRev += 1;
          return { rev: settingsRev, savedAt: app.now, needsSync: false };
        }),
      setUIState: (patch) =>
        run<void>("app.setUIState", [patch], () => {
          if (patch.lastStandupId != null) ui.lastStandupId = patch.lastStandupId;
          if (patch.lastView != null) ui.lastView = patch.lastView;
          if (patch.standupId != null && patch.lastPerson != null) {
            const lp: Record<string, string | undefined> = { ...(ui.lastPerson ?? {}) };
            lp[String(patch.standupId)] = patch.lastPerson;
            ui.lastPerson = lp as T.UIState["lastPerson"];
          }
          if (patch.window) ui.window = patch.window;
        }),
      openIssue: (issueKey) => run<void>("app.openIssue", [issueKey], () => undefined),
      openUrl: (url) => run<void>("app.openUrl", [url], () => undefined),
      diagnostics: () => run<T.Diagnostics>("app.diagnostics", [], () => app.diagnostics),
      reportPerf: (marks) => run<void>("app.reportPerf", [marks], () => undefined),
      logClientError: (message, stack) => run<void>("app.logClientError", [message, stack], () => undefined),
      mediaCache: () =>
        run<T.MediaCacheInfo>("app.mediaCache", [], () => {
          const cached = mediaCleared ? [] : allAttachments().filter((a) => a.image && a.cached !== "none");
          const full = cached.filter((a) => a.cached === "full");
          return {
            bytes: full.reduce((n, a) => n + a.bytes, 0),
            thumbBytes: cached.length * 24_000,
            files: cached.length + full.length,
            capMb: capMb(),
          };
        }),
      clearMediaCache: () =>
        run<T.MediaCacheInfo>("app.clearMediaCache", [], () => {
          mediaCleared = true;
          allAttachments().forEach((a) => (a.cached = "none"));
          return { bytes: 0, thumbBytes: 0, files: 0, capMb: capMb() };
        }),
    },

    standup: {
      list: () => run<T.StandupTab[]>("standup.list", [], () => tabs()),
      view: (standupId) => run<T.StandupView>("standup.view", [standupId], () => findView(standupId)),
    },

    config: {
      get: (id) => run<T.StandupConfig>("config.get", [id], () => findCfg(id)),
      create: () =>
        run<T.StandupConfig>("config.create", [], () => {
          const draft: T.StandupConfig = {
            id: nextStandupId++,
            rev: 1,
            position: configs.length,
            name: "New standup",
            space: null,
            board: null,
            scope: "sprint",
            extraFilter: "",
            filterCheck: null,
            columns: [],
            lanes: WALK.map((lane) => ({ lane, label: LANE_LABEL[lane], limitDays: 0, columns: [] })),
            unmappedStatuses: [],
            rowsMode: "fit",
            speakers: [],
            unassignedPosition: "last",
            reshuffleDaily: false,
            pulseDays: 28,
            showCommits: true,
            showPRs: true,
            showComments: true,
            shadeWeekends: true,
            doneWindow: "sprint",
            backlogRows: 12,
            needsSync: false,
            draft: true,
          };
          configs.push(draft);
          return draft;
        }),
      duplicate: (id) =>
        run<T.StandupConfig>("config.duplicate", [id], () => {
          const src = findCfg(id);
          const copy: T.StandupConfig = { ...clone(src), id: nextStandupId++, name: `${src.name} (copy)`, rev: 1, needsSync: false };
          configs.push(copy);
          reposition();
          const srcView = views.get(id);
          if (srcView) {
            const v = clone(srcView);
            v.standupId = copy.id;
            views.set(copy.id, v);
            refreshView(v, copy);
          }
          return copy;
        }),
      copySettingsFrom: (id, fromId) =>
        run<T.StandupConfig>("config.copySettingsFrom", [id, fromId], () => {
          const cfg = findCfg(id);
          const src = findCfg(fromId);
          Object.assign(cfg, {
            rowsMode: src.rowsMode,
            unassignedPosition: src.unassignedPosition,
            reshuffleDaily: src.reshuffleDaily,
            pulseDays: src.pulseDays,
            showCommits: src.showCommits,
            showPRs: src.showPRs,
            showComments: src.showComments,
            shadeWeekends: src.shadeWeekends,
            doneWindow: src.doneWindow,
            backlogRows: src.backlogRows,
          });
          cfg.lanes = cfg.lanes.map((l) => ({ ...l, limitDays: src.lanes.find((x) => x.lane === l.lane)?.limitDays ?? l.limitDays }));
          changed(cfg);
          return cfg;
        }),
      discardDraft: (id) =>
        run<void>("config.discardDraft", [id], () => {
          const cfg = findCfg(id);
          if (!cfg.draft || cfg.space !== null) return;
          configs = configs.filter((c) => c.id !== id);
          views.delete(id);
          reposition();
        }),
      delete: (id) =>
        run<T.SaveAck>("config.delete", [id], () => {
          const cfg = findCfg(id);
          archived.add(id);
          return ack(cfg);
        }),
      restore: (id) =>
        run<T.SaveAck>("config.restore", [id], () => {
          const cfg = findCfg(id);
          archived.delete(id);
          return ack(cfg);
        }),
      move: (id, toPosition) =>
        run<T.SaveAck>("config.move", [id, toPosition], () => {
          const cfg = findCfg(id);
          configs = configs.filter((c) => c !== cfg);
          configs.splice(Math.min(Math.max(toPosition, 0), configs.length), 0, cfg);
          reposition();
          cfg.rev += 1;
          return ack(cfg);
        }),
      update: (id, patch) =>
        run<T.SaveAck>("config.update", [id, patch], () => {
          const cfg = findCfg(id);
          if (patch.name != null) {
            const name = patch.name.trim();
            if (!name) throw invalid("Name is required.", "name");
            cfg.name = name;
          }
          if (patch.scope != null) cfg.scope = patch.scope;
          if (patch.extraFilter != null && patch.extraFilter !== cfg.extraFilter) {
            cfg.extraFilter = patch.extraFilter;
            cfg.needsSync = true;
          }
          if (patch.rowsMode != null) cfg.rowsMode = patch.rowsMode;
          if (patch.unassignedPosition != null) cfg.unassignedPosition = patch.unassignedPosition;
          if (patch.reshuffleDaily != null) cfg.reshuffleDaily = patch.reshuffleDaily;
          if (patch.pulseDays != null) cfg.pulseDays = patch.pulseDays;
          if (patch.showCommits != null) cfg.showCommits = patch.showCommits;
          if (patch.showPRs != null) cfg.showPRs = patch.showPRs;
          if (patch.showComments != null) cfg.showComments = patch.showComments;
          if (patch.shadeWeekends != null) cfg.shadeWeekends = patch.shadeWeekends;
          if (patch.doneWindow != null) cfg.doneWindow = patch.doneWindow;
          if (patch.backlogRows != null) cfg.backlogRows = patch.backlogRows;
          changed(cfg);
          return ack(cfg);
        }),
      setSpace: (id, spaceId) =>
        run<T.StandupConfig>("config.setSpace", [id, spaceId], () => {
          const cfg = findCfg(id);
          const space = catalog.spaces.find((s) => s.id === spaceId);
          if (!space) throw notFound("Space");
          cfg.space = { ...space };
          cfg.board = null;
          cfg.columns = [];
          cfg.draft = true;
          cfg.needsSync = true;
          syncLaneColumns(cfg);
          changed(cfg);
          return cfg;
        }),
      setBoard: (id, boardId) =>
        run<T.StandupConfig>("config.setBoard", [id, boardId], () => {
          const cfg = findCfg(id);
          const board = catalog.boards.find((b) => b.id === boardId);
          if (!board) throw notFound("Board");
          if (!cfg.space || board.spaceKey !== cfg.space.key) throw invalid("That board is not in this space.", "board");
          cfg.board = { id: board.id, name: board.name, type: board.type };
          if (board.type === "kanban") cfg.scope = "board";
          cfg.columns = clone(board.columns);
          syncLaneColumns(cfg);
          cfg.draft = false;
          cfg.needsSync = true;
          if (!views.has(id)) views.set(id, emptyView(cfg));
          changed(cfg);
          return cfg;
        }),
      setColumnLane: (id, columnName, lane) =>
        run<T.SaveAck>("config.setColumnLane", [id, columnName, lane], () => {
          const cfg = findCfg(id);
          const col = cfg.columns.find((c) => c.columnName === columnName);
          if (!col) throw notFound("Column");
          if (col.lane !== lane) col.order = 1e9; // joins the end of its new lane
          col.lane = lane;
          col.auto = false;
          syncLaneColumns(cfg);
          changed(cfg);
          return ack(cfg);
        }),
      moveColumn: (id, columnName, toIndex) =>
        run<T.SaveAck>("config.moveColumn", [id, columnName, toIndex], () => {
          const cfg = findCfg(id);
          const col = cfg.columns.find((c) => c.columnName === columnName);
          if (!col) throw notFound("Column");
          const group = cfg.columns.filter((c) => c.lane === col.lane && c !== col).sort((a, b) => a.order - b.order);
          group.splice(Math.max(0, Math.min(toIndex, group.length)), 0, col);
          group.forEach((c, i) => (c.order = i));
          changed(cfg);
          return ack(cfg);
        }),
      setWalkOrder: (id, lanes) =>
        run<T.SaveAck>("config.setWalkOrder", [id, lanes], () => {
          const cfg = findCfg(id);
          if (lanes.length !== WALK.length || !WALK.every((l) => lanes.includes(l))) {
            throw invalid("The walk order must list the four working lanes once each.", "lanes");
          }
          const byLane = new Map(cfg.lanes.map((l): [string, T.LaneInfo] => [l.lane, l]));
          cfg.lanes = lanes.flatMap((l) => {
            const row = byLane.get(l);
            return row ? [row] : [];
          });
          changed(cfg);
          return ack(cfg);
        }),
      setLaneLimit: (id, lane, days) =>
        run<T.SaveAck>("config.setLaneLimit", [id, lane, days], () => {
          const cfg = findCfg(id);
          if (!Number.isInteger(days) || days < 0) throw invalid("A lane limit is 0 (no limit) or more days.", "limitDays");
          const row = cfg.lanes.find((l) => l.lane === lane);
          if (!row) throw notFound("Lane");
          row.limitDays = days;
          changed(cfg);
          return ack(cfg);
        }),
      setSpeakerIncluded: (id, accountId, included) =>
        run<T.SaveAck>("config.setSpeakerIncluded", [id, accountId, included], () => {
          const cfg = findCfg(id);
          const s = cfg.speakers.find((x) => x.accountId === accountId);
          if (!s) throw notFound("Speaker");
          s.included = included;
          changed(cfg);
          return ack(cfg);
        }),
      moveSpeaker: (id, accountId, toPosition) =>
        run<T.SaveAck>("config.moveSpeaker", [id, accountId, toPosition], () => {
          const cfg = findCfg(id);
          const from = cfg.speakers.findIndex((x) => x.accountId === accountId);
          const moved = cfg.speakers.splice(from, 1)[0];
          if (!moved) throw notFound("Speaker");
          cfg.speakers.splice(Math.min(Math.max(toPosition, 0), cfg.speakers.length), 0, moved);
          cfg.speakers.forEach((s, i) => (s.position = i));
          changed(cfg);
          return ack(cfg);
        }),
      sortSpeakers: (id, mode) =>
        run<T.SpeakerConfig[]>("config.sortSpeakers", [id, mode], () => {
          const cfg = findCfg(id);
          let list: T.SpeakerConfig[];
          if (mode === "az") list = [...cfg.speakers].sort((a, b) => a.name.localeCompare(b.name));
          else if (mode === "active") list = [...cfg.speakers].sort((a, b) => b.active - a.active || a.name.localeCompare(b.name));
          else if (mode === "shuffle") list = seededOrder(cfg.speakers, id);
          else throw invalid("Unknown sort mode.", "mode");
          list.forEach((s, i) => (s.position = i));
          cfg.speakers = list;
          changed(cfg);
          return cfg.speakers;
        }),
      addSpeaker: (id, accountId) =>
        run<T.SpeakerConfig[]>("config.addSpeaker", [id, accountId], () => {
          const cfg = findCfg(id);
          const u = catalog.users.find((x) => x.accountId === accountId);
          if (!u) throw notFound("User");
          if (cfg.speakers.some((s) => s.accountId === accountId)) throw new AppError("conflict", "Already on this standup.");
          cfg.speakers.push({
            accountId,
            name: u.displayName,
            initials: u.initials,
            position: cfg.speakers.length,
            included: true,
            manual: true,
            active: 0,
            note: "no tickets right now",
          });
          changed(cfg);
          return cfg.speakers;
        }),
      removeSpeaker: (id, accountId) =>
        run<T.SaveAck>("config.removeSpeaker", [id, accountId], () => {
          const cfg = findCfg(id);
          const s = cfg.speakers.find((x) => x.accountId === accountId);
          if (!s) throw notFound("Speaker");
          cfg.speakers = cfg.speakers.filter((x) => x !== s);
          cfg.speakers.forEach((x, i) => (x.position = i));
          changed(cfg);
          return ack(cfg);
        }),
    },

    connection: {
      get: () => run<T.Connection>("connection.get", [], () => connection),
      connect: (input) =>
        run<T.Connection>("connection.connect", [input], () => {
          if (!input.baseUrl.trim() || !input.account.trim() || !input.secret) {
            throw invalid("Fill in the site, the account and the token.");
          }
          connection = { ...connection, state: "ok", source: input.source, baseUrl: input.baseUrl.trim(), account: input.account.trim() };
          return connection;
        }),
      disconnect: (deleteContent) =>
        run<void>("connection.disconnect", [deleteContent], () => {
          connection = { ...connection, state: "missing" };
        }),
      searchSpaces: (query) =>
        run<T.SpaceOption[]>("connection.searchSpaces", [query], () =>
          catalog.spaces.filter((s) => matches(query, s.key, s.name)).map((s) => ({ id: s.id, key: s.key, name: s.name })),
        ),
      searchBoards: (spaceKey, query) =>
        run<T.BoardOption[]>("connection.searchBoards", [spaceKey, query], () =>
          catalog.boards
            .filter((b) => b.spaceKey === spaceKey && matches(query, b.name))
            .map((b) => ({ id: b.id, name: b.name, type: b.type })),
        ),
      searchUsers: (standupId, query) =>
        run<T.UserOption[]>("connection.searchUsers", [standupId, query], () => {
          const cfg = findCfg(standupId);
          return catalog.users
            .filter((u) => matches(query, u.displayName))
            .map((u) => ({
              accountId: u.accountId,
              displayName: u.displayName,
              initials: u.initials,
              onBoard: cfg.speakers.some((s) => s.accountId === u.accountId),
            }));
        }),
      validateFilter: (standupId, expr) =>
        run<T.FilterCheck>("connection.validateFilter", [standupId, expr], () => {
          findCfg(standupId);
          const opens = expr.split("(").length - 1;
          const closes = expr.split(")").length - 1;
          const errors = opens === closes ? [] : ["Unbalanced parentheses."];
          return { ok: errors.length === 0, errors, checkedAt: app.now };
        }),
      ticketFields: () => run<T.TicketFieldPrefs>("connection.ticketFields", [], () => fieldPrefs),
      pinTicketField: (fieldId) =>
        run<T.TicketFieldPrefs>("connection.pinTicketField", [fieldId], () => {
          const opt = fieldPrefs.available.find((f) => f.fieldId === fieldId);
          if (!opt) throw notFound("Field");
          fieldPrefs.available = fieldPrefs.available.filter((f) => f !== opt);
          fieldPrefs.pinned.push({ fieldId, name: opt.name, kind: opt.kind, position: fieldPrefs.pinned.length, hidden: false });
          return fieldPrefs;
        }),
      unpinTicketField: (fieldId) =>
        run<T.TicketFieldPrefs>("connection.unpinTicketField", [fieldId], () => {
          const pref = fieldPrefs.pinned.find((f) => f.fieldId === fieldId);
          if (!pref) throw notFound("Field");
          fieldPrefs.pinned = fieldPrefs.pinned.filter((f) => f !== pref).map((f, i) => ({ ...f, position: i }));
          fieldPrefs.available = [...fieldPrefs.available, { fieldId, name: pref.name, kind: pref.kind, custom: true }].sort((a, b) =>
            a.name.localeCompare(b.name),
          );
          return fieldPrefs;
        }),
      moveTicketField: (fieldId, toPosition) =>
        run<T.SaveAck>("connection.moveTicketField", [fieldId, toPosition], () => {
          const pref = fieldPrefs.pinned.find((f) => f.fieldId === fieldId);
          if (!pref) throw notFound("Field");
          const rest = fieldPrefs.pinned.filter((f) => f !== pref);
          rest.splice(Math.max(0, Math.min(toPosition, rest.length)), 0, pref);
          fieldPrefs.pinned = rest.map((f, i) => ({ ...f, position: i }));
          settingsRev += 1;
          return { rev: settingsRev, savedAt: app.now, needsSync: false };
        }),
      setTicketFieldHidden: (fieldId, hidden) =>
        run<T.TicketFieldPrefs>("connection.setTicketFieldHidden", [fieldId, hidden], () => {
          const known = [...fieldPrefs.pinned, ...fieldPrefs.available, ...fieldPrefs.hidden].find((f) => f.fieldId === fieldId);
          if (!known) throw notFound("Field");
          const pinned = fieldPrefs.pinned.find((f) => f.fieldId === fieldId);
          fieldPrefs.hidden = fieldPrefs.hidden.filter((f) => f.fieldId !== fieldId);
          if (hidden) fieldPrefs.hidden.push({ fieldId, name: known.name, kind: known.kind, position: pinned?.position ?? -1, hidden: true });
          fieldPrefs.pinned = fieldPrefs.pinned.map((f) => (f.fieldId === fieldId ? { ...f, hidden } : f));
          return fieldPrefs;
        }),
    },

    sync: {
      start: (standupId, mode) =>
        run<number>("sync.start", [standupId, mode], () => {
          const cfg = findCfg(standupId);
          if (mode !== "incremental" && mode !== "full") throw invalid("Unknown sync mode.", "mode");
          const runId = nextRunId++;
          cfg.needsSync = false;
          const v = views.get(standupId);
          if (v) {
            v.sync = { ...idleSync(standupId, app.now), runId, mode };
            v.lastSyncedAt = app.now;
          }
          bus.emit("sync:started", { runId, standupId, mode, trigger: "manual" });
          bus.emit("sync:finished", {
            runId,
            standupId,
            status: "ok",
            errorCode: "",
            errorMessage: "",
            warnings: [],
            finishedAt: app.now,
            stats: { issues: v?.counts.active ?? 0, requests: 0, ms: 0 },
          });
          bus.emit("data:changed", { standupId, what: "view" });
          return runId;
        }),
      cancel: (standupId) =>
        run<void>("sync.cancel", [standupId], () => {
          findCfg(standupId);
        }),
      status: () => run<T.SyncStatus[]>("sync.status", [], () => statuses()),
    },

    ticket: {
      get: (standupId, issueId) => run<T.TicketDetail>("ticket.get", [standupId, issueId], () => findTicket(standupId, issueId)),
      transitions: (issueId) =>
        run<T.TransitionList>("ticket.transitions", [issueId], () => {
          const url = tickets.get(issueId)?.url ?? [...views.values()].flatMap((v) => v.tickets).find((x) => x.id === issueId)?.url ?? "";
          return { items: TRANSITIONS.map((x) => ({ ...x, url })), fetchedAt: app.now, offline: false };
        }),
      transition: (standupId, issueId, transitionId) =>
        run<T.TicketDetail>("ticket.transition", [standupId, issueId, transitionId], () => {
          const t = findTicket(standupId, issueId);
          const tr = TRANSITIONS.find((x) => x.id === transitionId);
          if (!tr) throw new AppError("write_rejected", "That transition is not available.");
          if (tr.needsScreen) throw new AppError("transition_needs_screen", "This transition needs more information — open in Jira");
          patchRows(issueId, (r) => {
            r.lane = tr.toLane;
            r.statusName = tr.toStatusName;
            r.daysInLane = 0;
            r.overLimit = false;
          });
          const status = stateRow(t, "status");
          if (status) status.text = tr.toStatusName;
          emitUpdated(t, ["status"]);
          return t;
        }),
      assign: (standupId, issueId, accountId) =>
        run<T.TicketDetail>("ticket.assign", [standupId, issueId, accountId], () => {
          const t = findTicket(standupId, issueId);
          patchRows(issueId, (r) => (r.assignee = accountId));
          const assignee = stateRow(t, "assignee");
          if (assignee) assignee.users = accountId ? [userRef(accountId)] : [];
          emitUpdated(t, ["assignee"]);
          return t;
        }),
      setFlag: (standupId, issueId, flagged) =>
        run<T.TicketDetail>("ticket.setFlag", [standupId, issueId, flagged], () => {
          const t = findTicket(standupId, issueId);
          patchRows(issueId, (r) => (r.blocked = flagged));
          const flag = stateRow(t, "flagged");
          if (flag) {
            flag.text = flagged ? "Flagged" : "Not flagged";
            if (!flagged) flag.sub = "";
          }
          emitUpdated(t, ["flag"]);
          return t;
        }),
      addComment: (standupId, issueId, input) =>
        run<T.TicketDetail>("ticket.addComment", [standupId, issueId, input], () => {
          const t = findTicket(standupId, issueId);
          if (!input.text.trim()) throw invalid("A comment needs some text.", "text");
          t.comments.push({
            id: `mock-${nextCommentId++}`,
            author: { ...SELF },
            createdAt: app.now,
            updatedAt: app.now,
            edited: false,
            visibility: "",
            body: plainDoc(input.text),
          });
          drafts.delete(issueId);
          t.draft = { text: "", mentions: [] };
          emitUpdated(t, ["comments"]);
          return t;
        }),
      refresh: (standupId, issueId) => run<T.TicketDetail>("ticket.refresh", [standupId, issueId], () => findTicket(standupId, issueId)),
      draft: (issueId) =>
        run<T.CommentInput>("ticket.draft", [issueId], () => drafts.get(issueId) ?? tickets.get(issueId)?.draft ?? { text: "", mentions: [] }),
      saveDraft: (issueId, input) =>
        run<T.SaveAck>("ticket.saveDraft", [issueId, input], () => {
          const next: T.CommentInput = input.text === "" ? { text: "", mentions: [] } : clone(input);
          if (input.text === "") drafts.delete(issueId);
          else drafts.set(issueId, next);
          const t = tickets.get(issueId);
          if (t) t.draft = clone(next);
          settingsRev += 1;
          return { rev: settingsRev, savedAt: app.now, needsSync: false };
        }),
      ensureMedia: (attachmentId) =>
        run<T.AttachmentView>("ticket.ensureMedia", [attachmentId], () => {
          const a = allAttachments().find((x) => x.id === attachmentId);
          if (!a) throw notFound("Attachment");
          if (a.image && a.cached !== "full") {
            a.cached = "full";
            mediaCleared = false;
            const owner = [...tickets.values()].find((t) => t.attachments.includes(a));
            bus.emit("media:ready", { attachmentId, issueId: owner?.issueId ?? 0, cached: "full" });
          }
          return a;
        }),
      openAttachment: (attachmentId) =>
        run<void>("ticket.openAttachment", [attachmentId], () => {
          if (!allAttachments().some((x) => x.id === attachmentId)) throw notFound("Attachment");
        }),
      searchMentions: (standupId, query) =>
        run<T.UserOption[]>("ticket.searchMentions", [standupId, query], () => {
          const cfg = findCfg(standupId);
          return catalog.users
            .filter((u) => matches(query, u.displayName))
            .map((u) => ({
              accountId: u.accountId,
              displayName: u.displayName,
              initials: u.initials,
              onBoard: cfg.speakers.some((s) => s.accountId === u.accountId),
            }));
        }),
    },

    sink: {
      kinds: () => run<T.SinkKind[]>("sink.kinds", [], () => app.sinkKinds),
      list: () => run<T.SinkConfig[]>("sink.list", [], () => sinks),
      save: (input) =>
        run<T.SinkConfig>("sink.save", [input], () => {
          const name = input.name.trim();
          if (!name) throw invalid("Name is required.", "name");
          if (!app.sinkKinds.some((k) => k.kind === input.kind)) throw new AppError("unsupported", "Unknown sink kind.");
          const existing = input.id ? sinks.find((s) => s.id === input.id) : undefined;
          if (input.id && !existing) throw notFound("Sink");
          const saved: T.SinkConfig = {
            id: existing?.id ?? nextSinkId++,
            kind: input.kind,
            name,
            standupId: input.standupId,
            config: { ...(input.config ?? {}) },
            hasSecret: input.secret != null ? input.secret !== "" : (existing?.hasSecret ?? false),
            sendOn: input.sendOn,
            enabled: input.enabled,
            lastDelivery: existing?.lastDelivery ?? null,
          };
          sinks = existing ? sinks.map((s) => (s.id === saved.id ? saved : s)) : [...sinks, saved];
          return saved;
        }),
      delete: (sinkId) =>
        run<void>("sink.delete", [sinkId], () => {
          if (!sinks.some((s) => s.id === sinkId)) throw notFound("Sink");
          sinks = sinks.filter((s) => s.id !== sinkId);
          outbox = outbox.filter((o) => o.sinkId !== sinkId);
        }),
      send: (sinkId, standupId, req) =>
        run<number>("sink.send", [sinkId, standupId, req], () => {
          if (!sinks.some((s) => s.id === sinkId)) throw notFound("Sink");
          findCfg(standupId);
          if (req.kind !== "current") throw new AppError("unsupported", "Only the current standup can be sent in v1.");
          const item: T.OutboxItem = {
            id: nextOutboxId++,
            sinkId,
            standupId,
            cause: "manual",
            payloadKind: "cuisle.export.v1",
            status: "delivered",
            attempts: 1,
            errorCode: "",
            error: "",
            receipt: "mock",
            createdAt: app.now,
            deliveredAt: app.now,
          };
          outbox.push(item);
          sinks = sinks.map((s) => (s.id === sinkId ? { ...s, lastDelivery: item } : s));
          bus.emit("sink:delivered", { outboxId: item.id, sinkId, standupId, kind: req.kind, ref: "mock" });
          return item.id;
        }),
      outbox: (sinkId, limit) =>
        run<T.OutboxItem[]>("sink.outbox", [sinkId, limit], () =>
          outbox
            .filter((o) => o.sinkId === sinkId)
            .reverse()
            .slice(0, Math.max(0, limit)),
        ),
      retry: (outboxId) =>
        run<void>("sink.retry", [outboxId], () => {
          const item = outbox.find((o) => o.id === outboxId);
          if (!item) throw notFound("Outbox item");
          item.status = "delivered";
          item.attempts += 1;
          item.errorCode = "";
          item.error = "";
          item.deliveredAt = app.now;
        }),
    },

    history: {
      // v1 placeholder: bound and registered, but not implemented until the history milestone (architecture §3.2).
      range: (standupId) => run<T.HistoryRange>("history.range", [standupId], notYet),
      viewAsOf: (standupId, date) => run<T.StandupView>("history.viewAsOf", [standupId, date], notYet),
    },
    update: {
      status: () => run<T.UpdateStatus>("update.status", [], updateNow),
      checkNow: () =>
        run<T.UpdateStatus>("update.checkNow", [], () => {
          if (update.channel !== "") setUpdate({ lastCheckedAt: Date.now(), lastError: "" });
          return updateNow();
        }),
      install: () =>
        run<void>("update.install", [], () => {
          if (update.channel === "") throw new AppError("unsupported", "This copy of Cuisle doesn't update itself.");
          if (!update.available) throw notFound("Newer version");
          setUpdate({ phase: "downloading", progress: 0, error: "", errorCode: "" });
          setUpdate({ progress: 45 });
          setUpdate({ progress: 100 });
          const end = opts?.updateInstall ?? "ok";
          if (end === "download") {
            const message = "Couldn't download the update. Check your connection and try again.";
            setUpdate({ phase: "failed", progress: 0, error: message, errorCode: "download" });
            throw new AppError("offline", message);
          }
          setUpdate({ phase: "verifying" });
          if (end === "verify") {
            const message = "Couldn't verify the download, so nothing was installed.";
            setUpdate({ phase: "failed", progress: 0, error: message, errorCode: "verify" });
            throw new AppError("internal", message);
          }
          setUpdate({ phase: "installing" });
          setUpdate({ phase: "restarting" });
        }),
    },
  };

  return {
    ...api,
    calls,
    resetCalls: () => {
      calls.length = 0;
    },
    bus,
  };
}
